pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public {
        c = new RoundFactory();
        c.initialize();
    }
    function testFuzz_property(address newImpl) public {
        vm.assume(newImpl != address(0));
        vm.prank(c.owner());
        c.updateRoundImplementation(payable(newImpl));
        assertTrue(c.roundImplementation() == newImpl, "roundImplementation must equal the set value");
    }
}
